const ELEMENT_PROP_KEYS = new Set(["theme","accent","before","after","highlight","fontWeight","foldAt","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  before: "Keyframe every frame by hand.",
  after: "Install the scene. Edit the props.",
  highlight: "Edit the props.",
  fontWeight: 500,
  foldAt: 72,
  fontFamily: "Instrument Sans",
  scale: 1,
  delay: 0,
  speed: 1,
};

type DiffSwapElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof DiffSwapBase>;

const DiffSwapInner = forwardRef<
  HTMLDivElement,
  DiffSwapElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<DiffSwap>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <DiffSwapBase
          {...(componentProps as unknown as ComponentProps<typeof DiffSwapBase>)}
        />
      </div>
    </Sequence>
  );
});

export const DiffSwap = Interactive.withSchema({
  Component: DiffSwapInner,
  componentName: "<DiffSwap>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
